<script setup>
import { ref, computed, inject } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';

useMeta({ title: 'Material Estimates' });
const formatNumber = inject('formatNumber')
const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
});

const cbm = ref(null);
const selectedClass = ref('');


// Adjustable factors
const shrinkage = ref(45);
const wastage = ref('');


const classes = {

    30: [1, 1, 2], // Cement : Sand : Aggregate
    25: [1, 1.5, 3],
    20: [1, 2, 4],
    15: [1, 3, 6],
    10: [1, 4, 8]

};


// Material densities

const density = {

    cement: 1440,
    sand: 1600,
    aggregate: 1500

};



const result = computed(() => {


    if (!selectedClass.value || !cbm.value) {
        return {};
    }


    const ratio = classes[selectedClass.value];


    const cementPart = ratio[0];
    const sandPart = ratio[1];
    const aggregatePart = ratio[2];


    const totalParts =
        cementPart +
        sandPart +
        aggregatePart;



    /*
        Adjust material volume

        Example:
        Concrete = 1 CBM
        Shrinkage = 54%
        Wastage = 5%

        Result:
        1 × (1 + 0.54 + 0.05)
        = 1.59 CBM
    */

    const adjustmentFactor =
        1 +
        (shrinkage.value / 100) +
        (wastage.value / 100);



    const adjustedVolume =
        cbm.value * adjustmentFactor;



    const cementVolume =
        (cementPart / totalParts) *
        adjustedVolume;


    const sandVolume =
        (sandPart / totalParts) *
        adjustedVolume;


    const aggregateVolume =
        (aggregatePart / totalParts) *
        adjustedVolume;



    const cementKg =
        cementVolume * density.cement;


    const sandKg =
        sandVolume * density.sand;


    const aggregateKg =
        aggregateVolume * density.aggregate;



    const totalKg =
        cementKg +
        sandKg +
        aggregateKg;



    return {


        adjustedVolume:
            adjustedVolume.toFixed(3),


        cementVolume:
            cementVolume.toFixed(3),


        sandVolume:
            sandVolume.toFixed(3),


        aggregateVolume:
            aggregateVolume.toFixed(3),



        cementKg:
            cementKg.toFixed(2),


        cementBags:
            (cementKg / 50).toFixed(2),


        sandKg:
            sandKg.toFixed(2),


        aggregateKg:
            aggregateKg.toFixed(2),


        totalKg:
            totalKg.toFixed(2)

    };

});

const triggerPrint = (content) => {

    const printWindow = window.open('', '_blank');

    printWindow.document.write(content);

    printWindow.document.close();

    printWindow.focus();

    printWindow.print();

    printWindow.close();

};

const printEstimate = () => {

    const materialRows = [
        {
            name: 'Cement',
            ratio: classes[selectedClass.value][0],
            volume: result.value.cementVolume,
            density: 1440,
            weight: result.value.cementKg,
            bags: result.value.cementBags
        },
        {
            name: 'Sand',
            ratio: classes[selectedClass.value][1],
            volume: result.value.sandVolume,
            density: 1600,
            weight: result.value.sandKg,
            bags: '-'
        },
        {
            name: 'Aggregate',
            ratio: classes[selectedClass.value][2],
            volume: result.value.aggregateVolume,
            density: 1500,
            weight: result.value.aggregateKg,
            bags: '-'
        }
    ];


    const rows = materialRows.map((item, index) => `
        <tr>
            <td>${index + 1}</td>
            <td>${item.name}</td>
            <td class="text-right">${item.ratio}</td>
            <td class="text-right">${item.volume} CBM</td>
            <td class="text-right">${formatNumber(item.density)}</td>
            <td class="text-right">${formatNumber(item.weight)} KG</td>
            <td class="text-right">

${
    item.name === 'Cement'
    ? formatNumber(item.bags) + ' Bags'
    : item.volume + ' CBM'
}

</td>
        </tr>
    `).join('');



    const totalVolume = (
        Number(result.value.cementVolume) +
        Number(result.value.sandVolume) +
        Number(result.value.aggregateVolume)
    ).toFixed(3);



    const inclusiveFactor = (
        Number(shrinkage.value || 0) +
        Number(wastage.value || 0)
    ).toFixed(2);



    const user = JSON.parse(localStorage.getItem('user'));


    const printContent = `
